@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>🔍 Track Your Shipment</h2>
<p>Enter your tracking number below to check status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="e.g. SHP-001-2026"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Search
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>". Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header">
            <h4 class="mb-0">Tracking: @shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>
                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <span>@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</span>
                                @if (shipment.Status != "Delivered")
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
                                    <span class="text-muted ms-2">
                                        (@(daysLeft > 0 ? $"in {daysLeft} day(s)" : daysLeft == 0 ? "today" : $"{Math.Abs(daysLeft)} day(s) overdue"))
                                    </span>
                                }
                            }
                            else
                            {
                                <span class="text-muted">Not yet scheduled</span>
                            }
                        </dd>
                        <dt>Last Updated</dt>
                        <dd>@shipment.UpdatedAt.ToString("MMMM dd, yyyy h:mm tt") UTC</dd>
                    </dl>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool searched;
    private bool searching;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.TrackShipmentAsync(searchedNumber);
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

