                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "—")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-primary me-1" @onclick="() => EditShipment(s)">Edit</button>
                            <button class="btn btn-sm btn-outline-danger" @onclick="() => DeleteShipment(s.Id)">Delete</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">@FilteredShipments.Count of @allShipments.Count shipment(s)</p>
}

@if (showForm)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-lg">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">@(editingShipment.Id == 0 ? "Create Shipment" : "Edit Shipment")</h5>
                    <button type="button" class="btn-close" @onclick="CloseForm"></button>
                </div>
                <EditForm Model="editingShipment" OnValidSubmit="SaveShipment" FormName="shipmentForm">
                    <DataAnnotationsValidator />
                    <div class="modal-body">
                        <ValidationSummary class="text-danger" />
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Tracking Number</label>
                                <InputText class="form-control" @bind-Value="editingShipment.TrackingNumber" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Status</label>
                                <InputSelect class="form-select" @bind-Value="editingShipment.Status">
                                    <option value="Pending">Pending</option>
                                    <option value="In Transit">In Transit</option>
                                    <option value="Delivered">Delivered</option>
                                    <option value="Cancelled">Cancelled</option>
                                </InputSelect>
                            </div>
                        </div>
                        <div class="mb-3">
                            <label class="form-label">Description</label>
                            <InputText class="form-control" @bind-Value="editingShipment.Description" />
                        </div>
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Origin</label>
                                <InputText class="form-control" @bind-Value="editingShipment.Origin" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Destination</label>
                                <InputText class="form-control" @bind-Value="editingShipment.Destination" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Estimated Delivery</label>
                                <InputDate class="form-control" @bind-Value="editingShipment.EstimatedDelivery" />
                            </div>
                            <div class="col-md-6 mb-3">
                                <label class="form-label">Customer Email</label>
                                <InputText class="form-control" @bind-Value="editingShipment.CustomerEmail" />
                            </div>
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button type="button" class="btn btn-secondary" @onclick="CloseForm">Cancel</button>
                        <button type="submit" class="btn btn-primary" disabled="@saving">
                            @if (saving)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Save
                        </button>
                    </div>
                </EditForm>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto> allShipments = [];
    private string filterText = string.Empty;
    private string sortColumn = "TrackingNumber";
    private bool sortAscending = true;
    private bool loading = true;
    private string? errorMessage;
    private bool showForm;
    private bool saving;
    private ShipmentDto editingShipment = new();

    private List<ShipmentDto> FilteredShipments
    {
        get
        {
            var filtered = string.IsNullOrWhiteSpace(filterText)
                ? allShipments
                : allShipments.Where(s =>
                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                    s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase))
                    .ToList();

            return sortColumn switch
            {
                "TrackingNumber" => sortAscending ? filtered.OrderBy(s => s.TrackingNumber).ToList() : filtered.OrderByDescending(s => s.TrackingNumber).ToList(),
                "Description" => sortAscending ? filtered.OrderBy(s => s.Description).ToList() : filtered.OrderByDescending(s => s.Description).ToList(),
                "Destination" => sortAscending ? filtered.OrderBy(s => s.Destination).ToList() : filtered.OrderByDescending(s => s.Destination).ToList(),
                "Status" => sortAscending ? filtered.OrderBy(s => s.Status).ToList() : filtered.OrderByDescending(s => s.Status).ToList(),
                "EstimatedDelivery" => sortAscending ? filtered.OrderBy(s => s.EstimatedDelivery).ToList() : filtered.OrderByDescending(s => s.EstimatedDelivery).ToList(),
                _ => filtered
            };
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            loading = true;
            errorMessage = null;
            allShipments = await ShipmentService.GetShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column) =>
        sortColumn != column ? "" : sortAscending ? "▲" : "▼";

    private void ShowCreateForm()
    {
        editingShipment = new ShipmentDto { Status = "Pending" };
        showForm = true;
    }

    private void EditShipment(ShipmentDto shipment)
    {
        editingShipment = new ShipmentDto
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Description = shipment.Description,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = shipment.Status,
            EstimatedDelivery = shipment.EstimatedDelivery,
            CustomerEmail = shipment.CustomerEmail
        };
        showForm = true;
    }

    private async Task SaveShipment()
    {
        try
        {
            saving = true;
            if (editingShipment.Id == 0)
                await ShipmentService.CreateShipmentAsync(editingShipment);
            else
                await ShipmentService.UpdateShipmentAsync(editingShipment);

            showForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            saving = false;
        }
    }

    private async Task DeleteShipment(int id)
    {
        try
        {
            await ShipmentService.DeleteShipmentAsync(id);
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to delete: {ex.Message}";
        }
    }

    private void CloseForm() => showForm = false;

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Delivered" => "bg-success",
        "In Transit" => "bg-primary",
        "Pending" => "bg-warning text-dark",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

