+            var filtered = string.IsNullOrWhiteSpace(filterText)
+                ? allShipments
+                : allShipments.Where(s =>
+                    s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
+                    s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
+                    s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase))
+                    .ToList();
+
+            return sortColumn switch
+            {
+                "TrackingNumber" => sortAscending ? filtered.OrderBy(s => s.TrackingNumber).ToList() : filtered.OrderByDescending(s => s.TrackingNumber).ToList(),
+                "Description" => sortAscending ? filtered.OrderBy(s => s.Description).ToList() : filtered.OrderByDescending(s => s.Description).ToList(),
+                "Destination" => sortAscending ? filtered.OrderBy(s => s.Destination).ToList() : filtered.OrderByDescending(s => s.Destination).ToList(),
+                "Status" => sortAscending ? filtered.OrderBy(s => s.Status).ToList() : filtered.OrderByDescending(s => s.Status).ToList(),
+                "EstimatedDelivery" => sortAscending ? filtered.OrderBy(s => s.EstimatedDelivery).ToList() : filtered.OrderByDescending(s => s.EstimatedDelivery).ToList(),
+                _ => filtered
+            };
+        }
+    }
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        try
+        {
+            loading = true;
+            errorMessage = null;
+            allShipments = await ShipmentService.GetShipmentsAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load shipments: {ex.Message}";
+        }
+        finally
+        {
+            loading = false;
+        }
+    }
+
+    private void SortBy(string column)
+    {
+        if (sortColumn == column)
+            sortAscending = !sortAscending;
+        else
+        {
+            sortColumn = column;
+            sortAscending = true;
+        }
+    }
+
+    private string SortIndicator(string column) =>
+        sortColumn != column ? "" : sortAscending ? "▲" : "▼";
+
+    private void ShowCreateForm()
+    {
+        editingShipment = new ShipmentDto { Status = "Pending" };
+        showForm = true;
+    }
+
+    private void EditShipment(ShipmentDto shipment)
+    {
+        editingShipment = new ShipmentDto
+        {
+            Id = shipment.Id,
+            TrackingNumber = shipment.TrackingNumber,
+            Description = shipment.Description,
+            Origin = shipment.Origin,
+            Destination = shipment.Destination,
+            Status = shipment.Status,
+            EstimatedDelivery = shipment.EstimatedDelivery,
+            CustomerEmail = shipment.CustomerEmail
+        };
+        showForm = true;
+    }
+
+    private async Task SaveShipment()
+    {
+        try
+        {
+            saving = true;
+            if (editingShipment.Id == 0)
+                await ShipmentService.CreateShipmentAsync(editingShipment);
+            else
+                await ShipmentService.UpdateShipmentAsync(editingShipment);
+
+            showForm = false;
+            await LoadShipments();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to save: {ex.Message}";
+        }
+        finally
+        {
+            saving = false;
+        }
+    }
+
+    private async Task DeleteShipment(int id)
+    {
+        try
+        {
+            await ShipmentService.DeleteShipmentAsync(id);
+            await LoadShipments();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to delete: {ex.Message}";
+        }
+    }
+
+    private void CloseForm() => showForm = false;
+
+    private static string GetStatusBadgeClass(string status) => status switch
+    {
+        "Delivered" => "bg-success",
+        "In Transit" => "bg-primary",
+        "Pending" => "bg-warning text-dark",
+        "Cancelled" => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
